export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-bla-0001", "section": "service", "who": "rubric", "text": "Благовещение пресвятой владычицы нашей богородицы и приснодевы марии"},
  {"id": "cu-bla-0002", "section": "service", "who": "reader", "text": "НА МАЛОЙ ВЕЧЕРНЕ"},
  {"id": "cu-bla-0003", "section": "service", "who": "rubric", "text": "Ведати подобает, яко навечерие Благовещения аще случится в субботу, или неделю, поется сице."},
  {"id": "cu-bla-0004", "section": "service", "who": "reader", "text": "На Господи, воззвах: стихиры на 4, глас 4. Подобен: Званный свыше:"},
  {"id": "cu-bla-0005", "section": "service", "who": "reader", "text": "Ущедрив тварь Зиждитель, / милосердием же Своим преклоняемь, / во утробу Девы Богоотроковицы вселитися спешит. / К Нейже великий прииде Архангел, – / радуйся, – провещавая, – Богорадованная, / ныне с Тобою Бог наш. / Не ужасайся мене, Царева Архистратига, / обрела бо еси благодать, / юже погуби Ева прежде, прамати Твоя, / и зачнеши и родиши / Отцу Единосущнаго. (2)"},
  {"id": "cu-bla-0006", "section": "service", "who": "reader", "text": "Странно есть слово Твое и воззрение, / странны Твои глаголы и возвещения, – / Мария ко Ангелу, – / да не прельстиши Мене, / Дева бо есмь, брака не знающи, / глаголеши, яко зачну Необыменнаго, / и како вместит утроба Моя, / Егоже величества Небесная вместити не могут? / Авраамов кров да научит Тя ныне, / Бога вместивый, / прообразующий издалеча, Дево, / Богоприятную Твою утробу."},
  {"id": "cu-bla-0007", "section": "service", "who": "reader", "text": "В Назарет ныне град пришед, / град Тя одушевлен Царя Христа / Гавриил лобызает, вопия Тебе: / радуйся, Благословенная Богорадованная, / приимеши во утробе Твоей Бога воплощаема / и Тобою человечество / на древнее блаженство за благоутробие призывающа. / Благословен чрева Твоего / Божественный Плод безсмертный, / подаяй миру очищение / и велию милость."},
  {"id": "cu-bla-0008", "section": "service", "who": "reader", "text": "Слава, и ныне, глас 1: В шестый месяц Архистратиг послан бысть / к Тебе, Деве и Чистей, / возвестити Тебе слово спасения, / вкупе же и звати Тебе: / радуйся, Обрадованная, Господь с Тобою, / родиши Сына Превечнаго из Отца, / и спасет люди Своя от грех их."},
  {"id": "cu-bla-0009", "section": "service", "who": "reader", "text": "На стиховне стихиры, глас 8. Подобен: О, преславного чудесе:"},
  {"id": "cu-bla-0010", "section": "service", "who": "reader", "text": "Начальник Вышних сил, / с Небес в Назарет слетев, / Деву лобызает, – / радуйся, – глаголя, – / колеснице чистая Божества: / Тя от века Бог возлюби, в жилище изволи. / Раб Владычень, к Тебе пришельствуяй есмь вопити: / родиши бо Господа / и нетленна пребудеши. Стих:"},
  {"id": "cu-bla-0011", "section": "service", "who": "reader", "text": "Благовестите день от дне / спасение Бога нашего."},
  {"id": "cu-bla-0012", "section": "service", "who": "reader", "text": "Что твой вид огненный? – / Гавриилу Чистая со удивлением рече, – / что твое достоинство и словес сила? / Зачати Сына провещаваеши Ми, / Аз же искуса мужеска не вем, / отыди далече, не прельстиши человече, / якоже прежде Еву праматерь змий льстивый. Стих:"},
  {"id": "cu-bla-0013", "section": "service", "who": "reader", "text": "Воспойте Господеви песнь нову, / воспойте Господеви, вся земля."},
  {"id": "cu-bla-0014", "section": "service", "who": "reader", "text": "Дух Божий Пресвятый / приидет, Пречистая, на Тя, / Боговместимая Владычице, / и сила Вышняго осенит Тя, / и родиши Сына, / соблюдающа Твое девство неврежденно. / Сей Сын есть неродословим, / Сей, явлься, спасет люди Своя, / яко благоизволи."},
  {"id": "cu-bla-0015", "section": "service", "who": "reader", "text": "Слава, и ныне, глас 4: В шестый месяц послан бысть Архангел / к Деве Чистей / и, радоватися Ей прирек, / благовести из Нея Избавителю проити. / Темже, приемши целование, / зачат Тя, Превечнаго Бога, / несказанно благоволившаго вочеловечитися / во спасение душ наших."},
  {"id": "cu-bla-0016", "section": "service", "who": "reader", "text": "Тропарь, глас 4: Днесь спасения нашего главизна / и еже от века таинства явление: / Сын Божий Сын Девы бывает, / и Гавриил благодать благовествует. / Темже и мы с ним Богородице возопиим: / радуйся, Благодатная, / Господь с Тобою."},
  {"id": "cu-bla-0017", "section": "service", "who": "rubric", "text": "Благовещение пресвятой владычицы нашей богородицы и приснодевы марии"},
  {"id": "cu-bla-0018", "section": "service", "who": "reader", "text": "НА ВЕЛИЦЕЙ ВЕЧЕРНИ"},
  {"id": "cu-bla-0019", "section": "service", "who": "rubric", "text": "Сий праздник начинается от четвертка 3-я недели святых постов и восходит до среды светлыя седмицы. И аще есть пост, начинаем вечерню без кафизмы и без поклонов."},
  {"id": "cu-bla-0020", "section": "service", "who": "rubric", "text": "На"},
  {"id": "cu-bla-0021", "section": "service", "who": "reader", "text": "Господи, воззвах:"},
  {"id": "cu-bla-0022", "section": "service", "who": "rubric", "text": "ставим стихов 10 и поем Триоди самогласен дне, дважды, и подобны 3, и праздника 3, повторяюще две."},
  {"id": "cu-bla-0023", "section": "service", "who": "reader", "text": "Глас 6. Подобен: Всю отложивше:"},
  {"id": "cu-bla-0024", "section": "service", "who": "reader", "text": "Совет превечный / открывая Тебе, Отроковице, / Гавриил предста, / Тебе лобзая и вещая: / радуйся, земле ненасеянная; / радуйся, купино неопалимая; / радуйся, глубино неудобозримая; / радуйся, мосте, к Небесем преводяй, / и лествице высокая, / юже Иаков виде; / радуйся, Божественная стамно манны; / радуйся, разрешение клятвы; / радуйся, Адамово воззвание: / с Тобою Господь. (2)"},
  {"id": "cu-bla-0025", "section": "service", "who": "reader", "text": "Являешися Мне, яко человек, – / глаголет нетленная Отроковица ко Архистратигу, – / и како вещаеши глаголы паче человека? / Со Мною бо, рекл еси, Богу быти / и вселитися во утробу Мою. / И како буду, глаголи Ми, / вместилище пространное и место священия / Херувимы превосходящаго? / Да не прельстиши Мене лестию, / не бо познах сласти, / браку есмь непричастна, / како убо Отроча рожду? (2)"},
  {"id": "cu-bla-0026", "section": "service", "who": "reader", "text": "Бог идеже хощет, / побеждается естества чин, – / глаголет безплотный, – / и яже паче человека содеваются, / моим веруй истинным глаголом, / Всесвятая Пренепорочная. / Она же возопи: / буди Мне ныне по глаголу твоему, / и рожду Безплотнаго, / плоть от Мене заимствовавшаго, / яко да возведет человека, / яко един силен, / в первое достояние срастворением."},
  {"id": "cu-bla-0027", "section": "service", "who": "reader", "text": "Слава, и ныне, глас тойже, самогласен. Иоанна монаха:"},
  {"id": "cu-bla-0028", "section": "service", "who": "reader", "text": "Послан бысть с Небесе Гавриил Архангел / благовестити Деве зачатие / и, пришед в Назарет, / помышляше в себе, чудеси удивляяся: / о, како, в Вышних непостижим Сый от Девы раждается! / Имеяй престол Небо и подножие землю / во утробу вмещается Девичу! / На Негоже шестокрилатии и многоочитии зрети не могут, / словом единем от Сея воплотитися благоизволи. / Божие есть слово настоящее. / Что убо стою и не глаголю Деве: / радуйся, Благодатная, Господь с Тобою; / радуйся, Чистая Дево; / радуйся, Невесто Неневестная; / радуйся, Мати Живота, / благословен Плод чрева Твоего! Вход."},
  {"id": "cu-bla-0029", "section": "service", "who": "reader", "text": "Свете Тихий:"},
  {"id": "cu-bla-0030", "section": "service", "who": "rubric", "text": "Прокимен, и чтение дне, и праздника три."},
  {"id": "cu-bla-0031", "section": "service", "who": "reader", "text": "Бытия чтение (глава 28): Изыде Иаков от студенца клятвеннаго и иде в Харрань. И обрете место, и спа тамо: зайде бо солнце, / и взят от камения места того, и положи возглавие себе, и спа на месте оном. И сон виде. И се лествица, утверждена на земли, eяже глава досязаше до небес, и Ангели Божии восхождаху и низхождаху по ней. Господь же утверждашеся на ней, и рече: Аз Бог Авраамов, отца твоего, и Бог Исааков, не бойся: земля, идеже ты спиши на ней, тебе дам ю и семени твоему. И будет семя твое, яко песок земный, и распространится на море, и ливу, и север, и на востоки; и возблагословятся о тебе вся колена земная и о семени твоем. И се Аз с тобою, сохраняяй тя на всяком пути, аможе аще пойдеши. И возвращу тя в землю сию, яко не имам тебе оставити, дондеже сотворити Ми вся, елика глаголах тебе. И воста Иаков от сна своего, и рече: яко eсть Господь на месте сем, аз же не ведех. И убояся, и рече: яко страшно место сие; несть сие, но дом Божий и сия врата Небесная."},
  {"id": "cu-bla-0032", "section": "service", "who": "reader", "text": "Прoрочества Иезекиилева чтение (главы 43 и 44):"},
  {"id": "cu-bla-0033", "section": "service", "who": "reader", "text": "Тако глаголет Господь: будет от дне осмаго и прочее, сотворят иереи на олтари всесожжения вашего и яже спасения вашего, и прииму вы, глаголет Адонаи Господь. И обрати мя на путь врат святых внешних, зрящих на востоки, и сия бяху затворена. И рече Господь ко мне: врата сия затворена будут и не отверзутся, и никтоже пройдет сквозе их; яко Господь Бог Израилев пройдет ими, и будут затворена. Яко Игумен сядет в них снести хлеб, по пути Еламских врат внидет и по пути его изыдет. И введе мя по пути врат святых, сущих к северу, прямо храму, и видех, и се исполнь славы храм Господень."},
  {"id": "cu-bla-0034", "section": "service", "who": "reader", "text": "Притчей чтение (глава 9): Премудрость созда Себе дом и утверди столпов седмь. Закла Своя жертвенная, и раствори в чаши Своей вино, и уготова Свою трапезу. Посла Своя рабы, созывающи с высоким проповеданием на чашу, глаголющи: Иже есть безумен, да уклонится ко Мне. И требующим ума рече: Приидите, ядите Мой хлеб, и пийте вино, еже растворих вам. Оставите безумие и живи будете, и взыщите разума, да поживете, и исправите разум в ведении. Наказуяй злыя приимет себе безчестие, обличаяй же нечестиваго опорочит себе: обличения бо нечестивому раны ему. Не обличай злых, да не возненавидят тебе. Обличай премудра, и возлюбит тя. Даждь премудрому вину, и премудрший будет. Сказуй праведному, и приложит приимати. Начало премудрости страх Господень и совет святых разум: разумети бо закон помысла есть благаго. Сим бо образом многое поживеши время, и приложатся тебе лета живота. Таже,"},
  {"id": "cu-bla-0035", "section": "service", "who": "reader", "text": "Да исправится молитва моя:"},
  {"id": "cu-bla-0036", "section": "service", "who": "rubric", "text": "И поклоны 3 великия, и прочее преждесвященных."},
  {"id": "cu-bla-0037", "section": "service", "who": "rubric", "text": "Аще же несть преждесвященных. На"},
  {"id": "cu-bla-0038", "section": "service", "who": "reader", "text": "Господи, воззвах:"},
  {"id": "cu-bla-0039", "section": "service", "who": "rubric", "text": "стихиры подобны 3, в Триоди, и праздника 5."},
  {"id": "cu-bla-0040", "section": "service", "who": "reader", "text": "Слава, и ныне: Послан бысть:"},
  {"id": "cu-bla-0041", "section": "service", "who": "rubric", "text": "Вход. Прокимен. И чтения дне и праздника 3. Таже"},
  {"id": "cu-bla-0042", "section": "service", "who": "reader", "text": "Сподоби, Господи:"},
  {"id": "cu-bla-0043", "section": "service", "who": "rubric", "text": "На стиховне Триоди самогласен дне, дважды, и мученичен."},
  {"id": "cu-bla-0044", "section": "service", "who": "reader", "text": "Слава, и ныне: Днесь радость: По"},
  {"id": "cu-bla-0045", "section": "service", "who": "reader", "text": "Ныне отпущаеши:"},
  {"id": "cu-bla-0046", "section": "service", "who": "rubric", "text": "тропарь праздника, ектения и 3 поклоны великия, и отпуст. На трапезе же разрешаем на вино и елей, в кийлибо день случится, во славу Пресвятыя Богородицы."},
  {"id": "cu-bla-0047", "section": "service", "who": "rubric", "text": "Потреба есть ведати, яко аще случится Благовещение в которую субботу поста."},
  {"id": "cu-bla-0048", "section": "service", "who": "rubric", "text": "Чтутся чтения прежде дне и по сих праздника 5: 1."},
  {"id": "cu-bla-0049", "section": "service", "who": "reader", "text": "Вниде Моисей: 2."},
  {"id": "cu-bla-0050", "section": "service", "who": "reader", "text": "Господь созда мя: 3."},
  {"id": "cu-bla-0051", "section": "service", "who": "reader", "text": "Изыде Иаков: 4."},
  {"id": "cu-bla-0052", "section": "service", "who": "reader", "text": "Будет от дне осмаго: 5."},
  {"id": "cu-bla-0053", "section": "service", "who": "reader", "text": "Премудрость созда Себе дом:"},
  {"id": "cu-bla-0054", "section": "service", "who": "rubric", "text": "Подобне чтутся чтений праздника 5, аще Благовещение случится и в неделю."},
  {"id": "cu-bla-0055", "section": "service", "who": "rubric", "text": "Аще ли есть пост, чтутся вечер, три преждеписанныя и две на Литургии."},
  {"id": "cu-bla-0056", "section": "service", "who": "rubric", "text": "При часе же 1-м нощи ударяет в великий кампан довольно и потом во вся. И, собравшеся во храм, благословившу иерею, и кадящу, поем повечерие великое, и"},
  {"id": "cu-bla-0057", "section": "service", "who": "reader", "text": "С нами Бог:"},
  {"id": "cu-bla-0058", "section": "service", "who": "rubric", "text": "с пением, на глас 8, на оба лика. И обычныя тропари:"},
  {"id": "cu-bla-0059", "section": "service", "who": "choir", "text": "День прешед:"},
  {"id": "cu-bla-0060", "section": "service", "who": "rubric", "text": "По 1-м трисвятом тропарь праздника:"},
  {"id": "cu-bla-0061", "section": "service", "who": "choir", "text": "Днесь спасения нашего:"},
  {"id": "cu-bla-0062", "section": "service", "who": "rubric", "text": "По 2-м кондак праздника:"},
  {"id": "cu-bla-0063", "section": "service", "who": "choir", "text": "Взбранной Воеводе: И по"},
  {"id": "cu-bla-0064", "section": "service", "who": "choir", "text": "Слава в Вышних:"},
  {"id": "cu-bla-0065", "section": "service", "who": "rubric", "text": "творим исхождение в притвор. И бывает лития по обычаю."},
  {"id": "cu-bla-0066", "section": "service", "who": "reader", "text": "И поем стихиры праздника, самогласны 3. Глас 1. Византиево:"},
  {"id": "cu-bla-0067", "section": "service", "who": "reader", "text": "В шестый месяц Архистратиг послан бысть / к Тебе, Деве и Чистей, / возвестити Тебе слово спасения, / вкупе же и звати Тебе: / радуйся, Обрадованная, Господь с Тобою, / родиши Сына превечнаго из Отца, / и спасет люди Своя от грех их. Анатолиево:"},
  {"id": "cu-bla-0068", "section": "service", "who": "reader", "text": "В месяц шестый послан бысть с Небесе Гавриил Архангел / во град галилейский Назарет / принести Отроковице радость благовещения. / И, пришед к Ней, возопи, глаголя: / радуйся, Обрадованная, Господь с Тобою; / радуйся, вместилище невместимаго естества, / Егоже бо Небеса не вместиша, / утроба Твоя вмести, Благословенная; / радуйся, честное Адамово воззвание, Евино избавление, / и радость мира, / и веселие рода нашего."},
  {"id": "cu-bla-0069", "section": "service", "who": "reader", "text": "Послан бысть Архангел Гавриил с Небесе от Бога / к Деве нескверней во град галилейский Назарет / благовестити Ей страннаго образа зачатие. / Послан бысть раб безплотен / ко одушевленному граду и двери мысленней / возвестити Владычняго пришествия снитие. / Послан бысть воин Небесный ко Пресвятыя славы палате / проуготовати Зиждителю жилище неотъемлемо, / и, пришед к Ней, взываше: / радуйся, престоле огнезрачный, / четверозрачных преславнейший; / радуйся, седалище Царя Небеснаго; / радуйся, горо несекомая, приятелище пречестное, / в Тебе бо все исполнение вселися Божества телесне / благоволением Отца присносущнаго / и содейством Всесвятаго Духа; / радуйся, Обрадованная, Господь с Тобою."},
  {"id": "cu-bla-0070", "section": "service", "who": "reader", "text": "Аще суббота или неделя: Слава, глас 8. Иоанна монаха:"},
  {"id": "cu-bla-0071", "section": "service", "who": "reader", "text": "Да веселятся Небеса, и радуется земля, / ибо Отцу Соприсносущный, Собезначальный и Сопрестольный, / щедротство прием и человеколюбную милость, / Себе постави во истощание / благоволением и советом Отчим / и во утробу вселися Девичу, предочищенную Духом. / О, чудесе! Бог в человецех, / Невместимый в ложеснах, Безлетный в лето, / и еже преславнее, яко и зачатие безсеменно, / и истощание несказанно, и таинство елико. / Бог бо истощавается, и воплощается, и зиждется, / Ангелу к Чистей зачатие глаголавшу: / радуйся, Обрадованная, Господь с Тобою, / имеяй велию милость."},
  {"id": "cu-bla-0072", "section": "service", "who": "reader", "text": "И ныне, глас 2: Благовествует Гавриил Благодатней днесь: / радуйся, неневестная Мати и неискусобрачная. / Не удивляйся странному моему зраку, / ни ужасайся, Архангел бо есмь. / Змий прельсти Еву иногда, / ныне же благовествую Тебе радость, / и пребудеши нетленна, / и родиши Господа, Пречистая."},
  {"id": "cu-bla-0073", "section": "service", "who": "rubric", "text": "Аще же день постен:"},
  {"id": "cu-bla-0074", "section": "service", "who": "reader", "text": "Слава, и ныне: Благовествует Гавриил:"},
  {"id": "cu-bla-0075", "section": "service", "who": "rubric", "text": "Таже молитвы обычныя бдения. И, вшедше во храм, поем."},
  {"id": "cu-bla-0076", "section": "service", "who": "reader", "text": "На стиховне стихиры самогласны, глас 4:"},
  {"id": "cu-bla-0077", "section": "service", "who": "reader", "text": "В шестый месяц послан бысть Архангел / к Деве Чистей / и, радоватися Ей прирек, / благовести из Нея Избавителю проити. / Темже, приемши целование, / зачат Тя, Превечнаго Бога, / несказанно благоволившаго вочеловечитися / во спасение душ наших. Стих:"},
  {"id": "cu-bla-0078", "section": "service", "who": "reader", "text": "Благовестите день от дне / спасение Бога нашего."},
  {"id": "cu-bla-0079", "section": "service", "who": "reader", "text": "Языка, егоже не ведяше, / услыша Богородица: / глаголаше бо к Ней Архангел Благовещения глаголы, / отонудуже верно, приимше целование, / зачат Тя Превечнаго Бога. / Темже и мы, радующеся, вопием Ти: / из Нея воплотивыйся непреложно Боже, / мир мирови даруй / и душам нашим велию милость. Стих:"},
  {"id": "cu-bla-0080", "section": "service", "who": "reader", "text": "Воспойте Господеви песнь нову, / воспойте Господеви, вся земля."},
  {"id": "cu-bla-0081", "section": "service", "who": "reader", "text": "Се воззвание ныне явися нам: / паче слова Бог человеком соединяется, / Архангеловым гласом прелесть отгоняется. / Дева бо приемлет радость, / земная быша Небо, / мир разрешися первыя клятвы. / Да радуется тварь и гласы да воспоет: / Творче и Избавителю наш, / Господи, слава Тебе."},
  {"id": "cu-bla-0082", "section": "service", "who": "reader", "text": "Слава, и ныне, глас тойже. Андрея Иеросолимиты:"},
  {"id": "cu-bla-0083", "section": "service", "who": "reader", "text": "Днесь радость благовещения, / девственное торжество, / нижняя с Вышними совокупляются. / Адам обновляется, / и Ева первыя печали свобождается, / и сень нашего существа, / обожением приемшаго смешение, / Церковь Божия бысть. / О, таинство! Образ истощания неведомь, / богатство благости несказанно: / Ангел служит чудеси, / Девича утроба Сына приемлет, / Дух Святый низпосылается, / Отец свыше благоволит, / и изменение общим творится советом, / в немже и имже спасшеся, / вкупе с Гавриилом к Деве возопиим: / радуйся, Обрадованная, / из Неяже спасение – Христос Бог наш, / еже по нам прием естество, / к Себе возведе. / Того моли спастися душам нашим. Таже,"},
  {"id": "cu-bla-0084", "section": "service", "who": "reader", "text": "Ныне отпущаеши. И по"},
  {"id": "cu-bla-0085", "section": "service", "who": "reader", "text": "Отче наш:"},
  {"id": "cu-bla-0086", "section": "service", "who": "reader", "text": "На благословении хлебов тропарь, глас 4:"},
  {"id": "cu-bla-0087", "section": "service", "who": "reader", "text": "Днесь спасения нашего главизна / и еже от века таинства явление: / Сын Божий Сын Девы бывает, / и Гавриил благодать благовествует. / Темже и мы с ним Богородице возопиим: / радуйся, Благодатная, / Господь с Тобою. (3) И"},
  {"id": "cu-bla-0088", "section": "service", "who": "reader", "text": "Буди Имя Господне:"},
  {"id": "cu-bla-0089", "section": "service", "who": "rubric", "text": "с пением, трижды. И чтение праздника."},
  {"id": "cu-bla-0090", "section": "service", "who": "rubric", "text": "Благовещение пресвятой владычицы нашей богородицы и приснодевы марии"},
  {"id": "cu-bla-0091", "section": "service", "who": "reader", "text": "НА УТРЕНИ На"},
  {"id": "cu-bla-0092", "section": "service", "who": "reader", "text": "Бог Господь:"},
  {"id": "cu-bla-0093", "section": "service", "who": "reader", "text": "Тропарь, глас 4: Днесь спасения нашего главизна / и еже от века таинства явление: / Сын Божий Сын Девы бывает, / и Гавриил благодать благовествует. / Темже и мы с ним Богородице возопиим: / радуйся, Благодатная, / Господь с Тобою. трижды."},
  {"id": "cu-bla-0094", "section": "service", "who": "rubric", "text": "По 1-й кафизме оба седальна Триоди без ектении и чтение дне. По 2-й же кафизме ектения и"},
  {"id": "cu-bla-0095", "section": "service", "who": "reader", "text": "Седален праздника, глас 1. Подобен: Гроб Твой:"},
  {"id": "cu-bla-0096", "section": "service", "who": "reader", "text": "Великий воевода невещественных Ангел, во град Назарет представ, / Царя возвещает Тебе, Пречистая, веков и Господа, / радуйся, – глаголя Тебе, – Благословенная Марие, / непостижимое и несказанное чудо, человеков обновление."},
  {"id": "cu-bla-0097", "section": "service", "who": "reader", "text": "Слава, и ныне,"},
  {"id": "cu-bla-0098", "section": "service", "who": "rubric", "text": "тойже, и чтение праздника."},
  {"id": "cu-bla-0099", "section": "service", "who": "reader", "text": "По 3-й кафизме седален, глас 3. Подобен: Красоте:"},
  {"id": "cu-bla-0100", "section": "service", "who": "reader", "text": "Днесь вся тварь радуется, / яко – еже радуйся, – Тебе глаголет Архангел, / благословенная честная и пречистая Мати Христа Бога. / Днесь омрачается змиино шатание, / клятвы бо праотчи разрешается союз. / Темже и непрестанно вопием Ти: / радуйся, Обрадованная."},
  {"id": "cu-bla-0101", "section": "service", "who": "reader", "text": "Слава, и ныне, тойже."},
  {"id": "cu-bla-0102", "section": "service", "who": "rubric", "text": "По чтении же даются свещи братии."},
  {"id": "cu-bla-0103", "section": "service", "who": "reader", "text": "Величание: Архангельский глас / вопием Ти, Чистая: / радуйся, Благодатная, / Господь с Тобою."},
  {"id": "cu-bla-0104", "section": "service", "who": "reader", "text": "Псалом избранный: Боже суд Твой цареви даждь, / И правду Твою сыну цареву. / Судити людем Твоим в правде, / И нищим Твоим в суде. / Судит нищим людским, и спасет сыны убогих. / Благовестите день от дне спасение Бога нашего. / Господь даст глагол благовествующим силою многою. / Клятся Господь Давиду истиною, и не отвержется ея. / От плода чрева твоего посажду на престоле твоем. / Снидет яко дождь на руно, / И яко капля каплющая на землю. / И приклони небеса и сниде, и мрак под ногама Его. / Яко избра Господь Сиона, изволи его в жилище Себе. / Освятил есть селение Свое Вышний. / Бог посреде его, и не подвижится. / Пощадит нища и убога, и души убогих спасет. / Вси языцы поработают Ему. / Весь день благословят Его. / Будет утверждение на земли на версех гор. / Будет Имя Его благословено во веки. / И благословятся в Нем вся колена земная. / Благословен Господь Бог Израилев, творяй чудеса Един. / И благословено Имя славы Его в век, и в век века. / И исполнится славы Его вся земля: / Буди, буди. Слава, и ныне: Аллилуия (3)"},
  {"id": "cu-bla-0105", "section": "service", "who": "reader", "text": "."},
  {"id": "cu-bla-0106", "section": "service", "who": "reader", "text": "По полиелеи седален, глас 4. Подобен: Удивися:"},
  {"id": "cu-bla-0107", "section": "service", "who": "reader", "text": "Гавриил с Небесе, еже радуйся, зовет Честней, / яко зачнет во чреве Превечнаго Бога, / словом концы составльшаго. / Темже Мариам отвещаваше: / безмужна есмь и како рожду Сына? / Безсеменное рождение кто виде? И, сказуя, глаголаше Ангел Богородице и Деве: / найдет на Тя Дух Святый, / и сила Вышняго осенит Тя."},
  {"id": "cu-bla-0108", "section": "service", "who": "reader", "text": "Слава, и ныне, глас и подобен тойже: Послан бысть Гавриил к Деве Марии и возвести Ей неизглаголанную радость, / яко безсеменно зачнет и не истлеет, / родиши бо Сына, Предвечнаго Бога, и спасет люди Своя от грех их. / И свидетельствует пославый мя вопити Тебе, Благословенная, еже радуйся: / Дева родиши, и по рождестве паки пребудеши Дева."},
  {"id": "cu-bla-0109", "section": "service", "who": "rubric", "text": "И чтение праздника. Таже степенна, 1-й антифон 4-го гласа."},
  {"id": "cu-bla-0110", "section": "service", "who": "reader", "text": "Прокимен, глас 4: Благовестите день от дне / спасение Бога нашего. Стих:"},
  {"id": "cu-bla-0111", "section": "service", "who": "reader", "text": "Воспойте Господеви песнь нову, воспойте Господеви, вся земля. Всякое дыхание:"},
  {"id": "cu-bla-0112", "section": "service", "who": "reader", "text": "Евангелие от Луки, зачало 4: Во дни оны, воставши, Мариам, иде в горняя со тщанием, во град Иудов. И вниде в дом Захариин, и целова Елисавет. И бысть яко услыша Елисавет целование Мариино, взыграся младенец во чреве ея: и исполнися Духа Свята Елисавет. И возопи гласом велиим, и рече: благословена Ты в женах, и благословен плод чрева Твоего. И откуду мне сие, да прииде Мати Господа моего ко мне? Се бо, яко бысть глас целования Твоего во ушию моею, взыграся младенец радощами во чреве моем. И блаженна Веровавшая, яко будет совершение глаголанным Ей от Господа. И рече Мариам: величит душа Моя Господа, и возрадовася дух Мой о Бозе Спасе Моем. Яко призре на смирение Рабы Своея: се бо, отныне ублажат Мя вси роди. Яко сотвори Мне величие Сильный, и свято имя Его. Пребысть же Мариамь с нею яко три месяцы, и возвратися в дом Свой."},
  {"id": "cu-bla-0113", "section": "service", "who": "reader", "text": "По 50-м псалме стихира, глас 2. Самогласна:"},
  {"id": "cu-bla-0114", "section": "service", "who": "reader", "text": "Благовествует Гавриил Благодатней днесь: / радуйся, Неневестная Мати и Неискусобрачная. / Не удивляйся странному моему зраку, / ни ужасайся, Архангел бо есмь. / Змий прельсти Еву иногда, / ныне же благовествую Тебе радость, / и пребудеши нетленна, / и родиши Господа, Пречистая."},
  {"id": "cu-bla-0115", "section": "service", "who": "rubric", "text": "Канон праздника, ирмосы по дважды, тропари же на 12. Катавасия праздника, оба лика вкупе. А идеже трипеснец, тамо поем праздника со ирмосом на 6 и трипеснец на 8. Катавасия Триоди, оба лика вкупе."},
  {"id": "cu-bla-0116", "section": "service", "who": "rubric", "text": "Канон, творение кир Феофана, егоже краегранесие по алфавиту до 8-й песни. Глас 4."},
  {"id": "cu-bla-0117", "section": "service", "who": "reader", "text": "Песнь 1. Ирмос:"},
  {"id": "cu-bla-0118", "section": "service", "who": "reader", "text": "Отверзу уста моя, / и наполнятся Духа, / и слово отрыгну Царице Матери, / и явлюся, светло торжествуя, / и воспою, радуяся, Тоя чудеса."},
  {"id": "cu-bla-0119", "section": "service", "who": "reader", "text": "Да поет Тебе, Владычице, движа свирель духовную, Давид, праотец Твой: / послушай, Дщи, радованнаго гласа от Ангела, / радость бо возвещает Тебе неизглаголанную. Ангел возопи:"},
  {"id": "cu-bla-0120", "section": "service", "who": "reader", "text": "Вопию Тебе, веселяся, / приклони ухо Твое и вонми ми, / Божие возвещающу безсеменное зачатие, / обрела бо еси благодать пред Богом, / еяже никогдаже обрете другая, Всечистая."},
  {"id": "cu-bla-0121", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0122", "section": "service", "who": "reader", "text": "Да разумею, Ангеле, твоих глагол силу, / како будет, еже рекл еси, глаголи явственнейше? / Како зачну, Дева сущи, Отроковица? / Како же и Мати буду Зиждителя Моего? Ангел возопи:"},
  {"id": "cu-bla-0123", "section": "service", "who": "reader", "text": "Лестно мя вещати помышляеши, яко мню, / и радуюся, зря Твое утверждение. / Дерзай, Владычице, / Богу бо хотящу, удобь скончаются и преславная."},
  {"id": "cu-bla-0124", "section": "service", "who": "reader", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-bla-0125", "section": "service", "who": "reader", "text": "Твоя песнословцы, Богородице, / живый и независтный Источниче, / лик себе совокупльшия, духовно утверди, / в Божественней Твоей славе / венцев славы сподоби."},
  {"id": "cu-bla-0126", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0127", "section": "service", "who": "reader", "text": "Оскуде князь от Иуды, время наста прочее, / в неже явится языков надежда, Христос; / ты же, како Сего рожду, Дева сущи, скажи? Ангел возопи:"},
  {"id": "cu-bla-0128", "section": "service", "who": "reader", "text": "Ищеши от мене уведети Дево, образ зачатия Твоего, / но той несказанен есть: / Дух же Святый, зиждительною силою осенив Тя, совершит."},
  {"id": "cu-bla-0129", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0130", "section": "service", "who": "reader", "text": "Моя прамати, приемши разум змиин, пищи Божественныя изгнана бысть, / темже и Аз боюся целования страннаго твоего, / стыдящися поползновения. Ангел возопи:"},
  {"id": "cu-bla-0131", "section": "service", "who": "reader", "text": "Божий предстатель, послан есмь Божественный поведати Тебе совет. / Что мене боишися, Всенепорочная, паче Тебе боящагося? / Что благоговееши мне, Владычице, / Тебе честно благоговеющему?"},
  {"id": "cu-bla-0132", "section": "service", "who": "reader", "text": "Седален, глас 8. Подобен: Свирелей пастырских:"},
  {"id": "cu-bla-0133", "section": "service", "who": "reader", "text": "Слово Божие на землю ныне сниде, Ангел предста, вопия Деве: / радуйся, Благословенная, Яже печатию едина сохраншися, / во утробе приемши предвечнаго Слова и Господа, / да от прелести спасет, яко Бог, род человеческий."},
  {"id": "cu-bla-0134", "section": "service", "who": "reader", "text": "Слава, и ныне, глас тойже. Подобен: Повеленное:"},
  {"id": "cu-bla-0135", "section": "service", "who": "reader", "text": "Послан бысть с Небесе Архистратиг Гавриил от Бога, / скоро предста ко одушевленному граду, глаголя к Ней явственно: / Зиждителя приимеши, Дево, во утробе / и родиши Сего непреложне с плотию. / Темже послан есмь возвестити Тебе странное рождество, Чистая, / и стою, зовя Тебе: / радуйся, Невесто Неневестная."},
  {"id": "cu-bla-0136", "section": "service", "who": "reader", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-bla-0137", "section": "service", "who": "reader", "text": "Седяй в славе на престоле Божества / во облаце легце, / прииде Иисус Пребожественный / Нетленною Дланию и спасе зовущия: / слава, Христе, силе Твоей."},
  {"id": "cu-bla-0138", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0139", "section": "service", "who": "reader", "text": "Священную некую Деву раждающую слышах пророка, древле Еммануила прорекша; / хощу же разумети, како Божества растворение естество человеческое претерпит? Ангел возопи:"},
  {"id": "cu-bla-0140", "section": "service", "who": "reader", "text": "Явила есть купина, неопальна пребывши, / приемши пламень, обрадованная Всепетая, на Тебе таинства преславное: / по рождестве бо пребудеши Чистая Приснодева."},
  {"id": "cu-bla-0141", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0142", "section": "service", "who": "reader", "text": "Освещаемь сиянием Бога Вседержителя, / истины проповедниче, глаголи, Гаврииле, истиннейшая: / како, нетленне бывши чистоте Моей, / Слова рожду, с плотию Безплотнаго? Ангел возопи:"},
  {"id": "cu-bla-0143", "section": "service", "who": "reader", "text": "Со страхом Тебе, яко раб Госпоже, предстою, / с боязнию, Отроковице, ныне смотрити стыждуся Тебе, / яко бо дождь на руно, снидет на Тя Слово Отчее, яко благоволи."},
  {"id": "cu-bla-0144", "section": "service", "who": "reader", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-bla-0145", "section": "service", "who": "reader", "text": "Ужасошася всяческая / о Божественней славе Твоей: / Ты бо, Неискусобрачная Дево, / имела еси во утробе над всеми Бога / и родила еси безлетнаго Сына, / всем воспевающим Тя / мир подавающая."},
  {"id": "cu-bla-0146", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0147", "section": "service", "who": "reader", "text": "Разумети не могу Твоих словес известия: / чудеса бо быша множицею, / Божественною силою чудодействуема, / знамения и образы законнии, / роди же дева неискусомужне никогдаже. Ангел возопи:"},
  {"id": "cu-bla-0148", "section": "service", "who": "reader", "text": "Дивит, Всенепорочная, и странно бо чудо Твое, / едина бо Ты всех Царя приимеши во утробе воплощаема, / и Тя прообразуют пророческая речения, и гадания, и законнии образы."},
  {"id": "cu-bla-0149", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0150", "section": "service", "who": "reader", "text": "Всеми Невместимый и всеми Невидимый, / како сей может во чреве девиче вселитися, еже Сам созда? / Како же и зачну Бога Слова, собезначальна Отцу и Духу? Ангел возопи:"},
  {"id": "cu-bla-0151", "section": "service", "who": "reader", "text": "К Твоему праотцу Давиду обещався / посадити от плода Твоего чрева на престоле царства его, / Иаковлю Тя доброту, едину избра в словесное селение."},
  {"id": "cu-bla-0152", "section": "service", "who": "reader", "text": "Песнь 6. Ирмос:"},
  {"id": "cu-bla-0153", "section": "service", "who": "reader", "text": "Возопи, прообразуя погребение тридневное, / пророк Иона, в ките моляся: / от тли избави мя, / Иисусе, Царю сил."},
  {"id": "cu-bla-0154", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0155", "section": "service", "who": "reader", "text": "Глагол твоих, Гаврииле, глас радованен приемши, веселия Божественнаго исполнихся: / радость бо поведаеши и веселие возвещаеши безконечное. Ангел возопи:"},
  {"id": "cu-bla-0156", "section": "service", "who": "reader", "text": "Тебе дадеся радость, Богомати Божественная, / Тебе, еже радуйся, вся тварь вопиет, Богоневесто: / Ты бо едина Мати Сына Божия пронаречеся, Чистая."},
  {"id": "cu-bla-0157", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0158", "section": "service", "who": "reader", "text": "Евы Мною ныне да упразднится осуждение, / да воздастся Мною долг днесь, / Мною заимствование древнее да дастся преисполнено. Ангел возопи:"},
  {"id": "cu-bla-0159", "section": "service", "who": "reader", "text": "Обещася Бог Аврааму праотцу / благословитися в семене его языком, Чистая, / Тобою же конец обещание приемлет днесь."},
  {"id": "cu-bla-0160", "section": "service", "who": "reader", "text": "Кондак, глас 8: Взбранной Воеводе победительная, / яко избавльшеся от злых, / благодарственная восписуем Ти, раби Твои, Богородице, / но, яко имущая державу непобедимую, / от всяких нас бед свободи, да зовем Ти: / радуйся, Невесто Неневестная. Икос:"},
  {"id": "cu-bla-0161", "section": "service", "who": "reader", "text": "Ангел предстатель с Небесе послан бысть рещи Богородице: радуйся! / И со безплотным гласом воплощаема Тя зря, Господи, ужасашеся / и стояше, зовый к Ней таковая: / радуйся, Еюже радость возсияет; / радуйся, Еюже клятва исчезнет. / Радуйся, падшаго Адама воззвание; / радуйся, слез Евиных избавление. / Радуйся, высото неудобовосходимая человеческими помыслы; / радуйся, глубино неудобозримая и Ангельскима очима. / Радуйся, яко еси Царево седалище; / радуйся, яко носиши носящаго вся. / Радуйся, звездо, являющая Солнце; / радуйся, утробо Божественнаго воплощения. / Радуйся, Еюже обновляется тварь; / радуйся, Еюже покланяемся Творцу. / Радуйся, Невесто Неневестная."},
  {"id": "cu-bla-0162", "section": "service", "who": "reader", "text": "Песнь 7. Ирмос:"},
  {"id": "cu-bla-0163", "section": "service", "who": "reader", "text": "Не послужиша твари Богомудрии / паче Создавшаго, / но, огненное прещение мужески поправше, / радовахуся, поюще: / препетый отцев Господь и Бог, благословен еси."},
  {"id": "cu-bla-0164", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0165", "section": "service", "who": "reader", "text": "Свет невещественный поведая, в вещественне телеси совокупляемь за милосердие многое, / светлое благовещение, Божественная проповедания, ныне взываеши Ми: / благословен, Всечистая, Плод Твоего чрева. Ангел возопи:"},
  {"id": "cu-bla-0166", "section": "service", "who": "reader", "text": "Радуйся, Владычице Дево, / радуйся, Пречистая, / радуйся, приятелище Божие, / радуйся, свещниче Света, Адамово воззвание, / Евы избавление, горо святая, / преявственное священие и чертог безсмертия."},
  {"id": "cu-bla-0167", "section": "service", "who": "rubric", "text": "Богородица рече:"},
  {"id": "cu-bla-0168", "section": "service", "who": "reader", "text": "Душу очисти, тело освяти, / церковь сотвори Мя вместительну Бога, / скинию Богоукрашену, одушевлен храм наитием Пресвятаго Духа / и Жизни чистую Матерь. Ангел возопи:"},
  {"id": "cu-bla-0169", "section": "service", "who": "reader", "text": "Яко многосветлую свещу и Богоделанен чертог, / вижу Тя ныне, яко злат кивот, / закона Подателя приими, Богоневесто, / благоизволившаго человеческое избавити Тобою тленное существо."},
  {"id": "cu-bla-0170", "section": "service", "who": "reader", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-bla-0171", "section": "service", "who": "reader", "text": "Слыши, Отроковице, Дево чистая, / да речет убо Гавриил / совет Вышняго древний истинный: / буди к приятию готова Божию, / Тобою бо Невместимый с человеки поживе. / Тем и, радуяся вопию: / благословите, вся дела Господня, Господа. Богородица:"},
  {"id": "cu-bla-0172", "section": "service", "who": "reader", "text": "Ум всяк побеждается земных, – отвеща Девица, – / ищущи, яже Мне вещаеши, преславная: / слышах твоя словеса, но боюся, ужасающися, / да не лестию Мя, яко Еву, далече послеши от Бога. / Но обаче се вопию: / благословите, вся дела Господня, Господа и превозносите Его во веки. Ангел:"},
  {"id": "cu-bla-0173", "section": "service", "who": "reader", "text": "Се Тебе недоуменное разрешися, – глаголет к сим Гавриил, – добре бо рекла, еси, вещь неудобопостижна. / Словесем Твоих устен повинующися прочее, / не сумнися, яко лести, якоже вещи, веруй. / Аз бо, радуяся, вопию: / благословите, вся дела Господня, Господа и превозносите Его во веки. Богородица:"},
  {"id": "cu-bla-0174", "section": "service", "who": "reader", "text": "Закон сей от Бога есть человеком, – Непорочная абие глаголет, – / от общия любве рождество происходит. / Не вем супружника сласти всеконечно, / како, убо глаголеши, яко рожду? / Боюся, еда лесть глаголеши? / Но обаче се вопию: / благословите, вся дела Господня, Господа и превозносите Его во веки. Ангел:"},
  {"id": "cu-bla-0175", "section": "service", "who": "reader", "text": "Глаголы, яже мне вещаеши, Чистая, – / Ангел паки глаголет, – / обычая есть рождества человеков смертных, / истинно Бога Тебе обещаваю, / паче слова же и смысла воплощаема, яко весть, из Тебе. / Темже и, радуяся, вопию: / благословите, вся дела Господня, Господа и превозносите Его во веки. Богородица:"},
  {"id": "cu-bla-0176", "section": "service", "who": "reader", "text": "Являешися Мне истины вещатель, – рече Дева, – / радости бо общия пришел еси благовестник. / Душу убо очистих с телом, и по глаголу твоему буди Мне, / да вселится Бог в Мя, к Немуже вопию с тобою: / благословите, вся дела Господня, Господа и превозносите Его во веки."},
  {"id": "cu-bla-0177", "section": "service", "who": "rubric", "text": "На 9-й песни паки вжигают свещи братия. Честнейшую: не поем, но поем припев праздника:"},
  {"id": "cu-bla-0178", "section": "service", "who": "reader", "text": "Благовествуй, земле, радость велию, / хвалите, небеса, Божию славу. Таже ирмос:"},
  {"id": "cu-bla-0179", "section": "service", "who": "reader", "text": "Яко одушевленному:"},
  {"id": "cu-bla-0180", "section": "service", "who": "rubric", "text": "Подобне и 2-й лик припев, и ирмос, и к прочим тропарем праздника тойже припев. У трипеснца же к тропарем припеваем:"},
  {"id": "cu-bla-0181", "section": "service", "who": "choir", "text": "Слава Тебе, Боже наш, слава Тебе."},
  {"id": "cu-bla-0182", "section": "service", "who": "rubric", "text": "К Богородичным припеваем припев праздника."},
  {"id": "cu-bla-0183", "section": "service", "who": "choir", "text": "Песнь 9. Ирмос:"},
  {"id": "cu-bla-0184", "section": "service", "who": "choir", "text": "Яко одушевленному Божию кивоту, / да никакоже коснется рука скверных. / Устне же верных, Богородице, немолчно, / глас Ангела воспевающе, / с радостию да вопиют: / радуйся, Благодатная, / Господь с Тобою."},
  {"id": "cu-bla-0185", "section": "service", "who": "choir", "text": "Паче смысла заченши Бога, естества обычая утаися, Отроковице, / Ты бо в рождестве матерскаго избежала еси тленнаго естества / и превышши сущи. / Темже достойно слышиши: / радуйся, Благодатная, Господь с Тобою."},
  {"id": "cu-bla-0186", "section": "service", "who": "choir", "text": "Како точиши млеко, Дево Чистая, не может изрещи язык землен, / странну бо естества показуеши вещь, законнаго рождества устав преходиши. / Темже достойно слышиши: / радуйся, Благодатная, Господь с Тобою."},
  {"id": "cu-bla-0187", "section": "service", "who": "choir", "text": "Тайно во священных писаниих / глаголася о Тебе, Мати Вышняго, / лествицу бо древле Иаков, Тя образующую, видев, рече: / степень Божия сия. / Темже достойно слышиши: / радуйся, Благодатная, Господь с Тобою."},
  {"id": "cu-bla-0188", "section": "service", "who": "choir", "text": "Чудное священноявленному Моисею / купина и огнь показа чудо, / ищай же конца в прехождении времен, во Отроковице чистей, рече, узрю. / Ейже, яко Богородице, да речется: / радуйся, Благодатная, Господь с Тобою."},
  {"id": "cu-bla-0189", "section": "service", "who": "choir", "text": "Даниил Тя гору нарече мысленную, / родительницу же Божию Исаия, / видит же, яко руно, Гедеон, / Давид же священие глаголет, дверь же Тя ин. / Гавриил же Тебе взывает: / радуйся, Благодатная, Господь с Тобою."},
  {"id": "cu-bla-0190", "section": "service", "who": "rubric", "text": "Таже ирмос Триоди, и праздника припев, и ирмос оба лика вкупе."},
  {"id": "cu-bla-0191", "section": "service", "who": "choir", "text": "Светилен. Подобен: Со ученики:"},
  {"id": "cu-bla-0192", "section": "service", "who": "choir", "text": "Ангельских сил Архистратиг / послан бысть от Бога Вседержителя к Чистей и Деве / благовестити странное и неизреченное чудо: / зане Бог, яко Человек, из Нея младодействуется без семене, / назидаяй весь человеческий род. / Людие, благовестите обновление мира."},
  {"id": "cu-bla-0193", "section": "service", "who": "choir", "text": "Слава, и ныне:"},
  {"id": "cu-bla-0194", "section": "service", "who": "choir", "text": "Ин светилен. Подобен: Жены, услышите:"},
  {"id": "cu-bla-0195", "section": "service", "who": "choir", "text": "Еже от века днесь познавается таинство Божие: / Бог Слово Сын Девы Марии за милосердие бывает, / и радость благовещения Гавриил провещавает. / С нимже возопием Ей: / радуйся, Мати Господня. На хвалитех"},
  {"id": "cu-bla-0196", "section": "service", "who": "choir", "text": "Всякое дыхание:"},
  {"id": "cu-bla-0197", "section": "service", "who": "choir", "text": "И поем стихиры, на 4. Глас 1. Подобен: Небесных чинов:"},
  {"id": "cu-bla-0198", "section": "service", "who": "choir", "text": "С Небесных кругов слетев Гавриил в Назарет, / прииде к Деве Марии, / вопия Ей: радуйся! / Зачнеши Сына, Адама древнейшаго, / Творца веков и Избавителя / вопиющих Тебе: / радуйся, Чистая."},
  {"id": "cu-bla-0199", "section": "service", "who": "choir", "text": "Соприсносущное Слово Пребезначального Отца, / не разлучився Горних, / ныне предста дольным, ради крайняго благоутробия, / милость прием, еже на ны поползновения, / и, Адамову нищету восприем, / вообразися в чуждее."},
  {"id": "cu-bla-0200", "section": "service", "who": "choir", "text": "Гавриил, Деве благовестие с Небесе принес, / вопияше: радуйся! / Зачнеши во чреве Твоем / Тобою вместимаго, / Невместимаго же всеми, / и раждающая явишися / от Отца прежде денницы возсиявшаго."},
  {"id": "cu-bla-0201", "section": "service", "who": "choir", "text": "Пресущественное Слово, / плотию вселився в Тя / Отчим советом, Богородице Дево, / назда род, иже по нам, / падший от древния клятвы. / Тем – еже радуйся – Тебе вси, Мати Христова, / со Ангелом вопием верно."},
  {"id": "cu-bla-0202", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 2. Феофаново:"},
  {"id": "cu-bla-0203", "section": "service", "who": "choir", "text": "Еже от века таинство открывается днесь, / и Сын Божий Сын человечь бывает: / да, хуждшее восприем, подаст ми лучшее. / Солгася древле Адам, / и Бог, возжелев быти, не бысть: / Человек бывает Бог, / да бога Адама соделает. / Да веселится тварь, да ликовствует естество, / яко Архангел Деве со страхом предстоит / и – еже радуйся – приносит, печали сопротивное. / За милосердие милости вочеловечивыйся, / Боже наш, слава Тебе."},
  {"id": "cu-bla-0204", "section": "service", "who": "rubric", "text": "Аще есть суббота или неделя, славословие великое, и ектении, и отпуст. Аще же день постен, поем на стиховне Триоди самогласен дне, дважды и мученичен."},
  {"id": "cu-bla-0205", "section": "service", "who": "choir", "text": "Слава, и ныне, праздника, глас 8: Да веселятся Небеса, и радуется земля, / ибо Отцу Соприсносущный, Собезначальный и Сопрестольный, / щедротство прием и человеколюбную милость, / Себе постави во истощание / благоволением и советом Отчим / и во утробу вселися Девичу, предочищенную Духом. / О, чудесе! Бог в человецех, / Невместимый в ложеснах, Безлетный в лето, / и еже преславнее, яко и зачатие безсеменно, / и истощание несказанно, и таинство елико. / Бог бо истощавается, и воплощается, и зиждется, / Ангелу к Чистей зачатие глаголавшу: / радуйся, Обрадованная, Господь с Тобою, / имеяй велию милость. Таже,"},
  {"id": "cu-bla-0206", "section": "service", "who": "choir", "text": "Благо есть: единожды. По"},
  {"id": "cu-bla-0207", "section": "service", "who": "choir", "text": "Отче наш:"},
  {"id": "cu-bla-0208", "section": "service", "who": "rubric", "text": "тропарь праздника, и ектения, в конец три поклоны великия, без отпуста утрени; дается же и святый елей братии, и поется стихира самогласна, и час 1-й с кафизмою. Тропарь и кондак праздника, и в конец три поклоны великия, и молитва:"},
  {"id": "cu-bla-0209", "section": "service", "who": "choir", "text": "Христе, Свете истинный:"},
  {"id": "cu-bla-0210", "section": "service", "who": "choir", "text": "Отпуст: Христос, истинный Бог наш, молитвами пречистыя Своея Матере, святых славных и всехвальных Апостол, святых праведных Богоотец Иоакима и Анны, и всех святых, помилует и спасет нас, яко Благ и Человеколюбец."},
  {"id": "cu-bla-0211", "section": "service", "who": "rubric", "text": "Благовещение пресвятой владычицы нашей богородицы и приснодевы марии"},
  {"id": "cu-bla-0212", "section": "service", "who": "choir", "text": "НА ЛИТУРГИИ"},
  {"id": "cu-bla-0213", "section": "service", "who": "rubric", "text": "В 3-й же час дне исходим со кресты с литиею вне монастыря и, возвращшеся, входим в трапезу и поем часы 3-й и 6-й с кафизмами без поклонов, тропарь и кондак праздника."},
  {"id": "cu-bla-0214", "section": "service", "who": "rubric", "text": "На часех же в кампан не ударяем, на 6-м часе поем тропарь паремии Триоди и прочая, по чину их, и паремия и чтем слово, емуже начало:"},
  {"id": "cu-bla-0215", "section": "service", "who": "choir", "text": "Паки радость благовещения:"},
  {"id": "cu-bla-0216", "section": "service", "who": "rubric", "text": "Присовокупляем же и 9-й час с кафизмою и чтением. Посем, Блаженны: скоро без пения и без поклонов."},
  {"id": "cu-bla-0217", "section": "service", "who": "choir", "text": "Помяни нас, Господи: Лик Небесный: Слава: Лик святых Ангел: Ослаби, остави: По"},
  {"id": "cu-bla-0218", "section": "service", "who": "choir", "text": "Отче наш:"},
  {"id": "cu-bla-0219", "section": "service", "who": "rubric", "text": "кондак праздника."},
  {"id": "cu-bla-0220", "section": "service", "who": "choir", "text": "Господи, помилуй, 40."},
  {"id": "cu-bla-0221", "section": "service", "who": "choir", "text": "Слава, и ныне: Честнейшую Херувим:"},
  {"id": "cu-bla-0222", "section": "service", "who": "rubric", "text": "и поклоны три великия и молитва:"},
  {"id": "cu-bla-0223", "section": "service", "who": "choir", "text": "Всесвятая Троице:"},
  {"id": "cu-bla-0224", "section": "service", "who": "rubric", "text": "и отпуст. И поем вечерню без кафизмы и без поклонов."},
  {"id": "cu-bla-0225", "section": "service", "who": "rubric", "text": "На"},
  {"id": "cu-bla-0226", "section": "service", "who": "choir", "text": "Господи, воззвах:"},
  {"id": "cu-bla-0227", "section": "service", "who": "rubric", "text": "поем Триоди самогласен дне, дважды, без мученична, и подобны Триоди три, и праздника три, и Архангела три."},
  {"id": "cu-bla-0228", "section": "service", "who": "choir", "text": "Стихиры праздника, глас 4. Самогласны:"},
  {"id": "cu-bla-0229", "section": "service", "who": "choir", "text": "Вшестый месяц послан бысть Архангел / к Деве Чистей / и, радоватися Ей прирек, / благовести из Нея Избавителю проити. / Темже, приемши целование, / зачат Тя, Превечнаго Бога, / несказанно благоволившаго вочеловечитися / во спасение душ наших."},
  {"id": "cu-bla-0230", "section": "service", "who": "choir", "text": "Языка, егоже не ведяше, услыша Богородица, / глаголаше бо к Ней Архангел благовещения глаголы, / отонудуже верно, приимши целование, / зачат Тя, Превечнаго Бога. / Темже и мы, радующеся, вопием Ти: / из Нея воплотивыйся непреложно Боже, / мир мирови даруй / и душам нашим велию милость."},
  {"id": "cu-bla-0231", "section": "service", "who": "choir", "text": "Се воззвание ныне явися нам, / паче Слова Бог человеком соединяется, / Архангеловым гласом прелесть отгоняется, / Дева бо приемлет радость, / земная быша Небо, / мир разрешися первыя клятвы. / Да радуется тварь и гласы да воспоет: / Творче и Избавителю наш, / Господи, слава Тебе."},
  {"id": "cu-bla-0232", "section": "service", "who": "choir", "text": "Архангела стихиры, глас 1. Подобен: Всехвальнии мученицы:"},
  {"id": "cu-bla-0233", "section": "service", "who": "choir", "text": "Гавриил великий, / ум Боговиднейший, светозарный и спасительный, / Свет Трисолнечный зрит / и поет с Вышними чины / Божественное и страшное пение, / молит даровати душам нашим / мир и велию милость."},
  {"id": "cu-bla-0234", "section": "service", "who": "choir", "text": "Великое таинство, / первее Ангелом неведомое / и прежде век соблюдаемое, / единому уверися тебе, Гаврииле, / и сие единей поведал еси Чистей, в Назарет пришед. / С Неюже моли / даровати душам нашим / мир и велию милость."},
  {"id": "cu-bla-0235", "section": "service", "who": "rubric", "text": "К 11-му стиху припев:"},
  {"id": "cu-bla-0236", "section": "service", "who": "choir", "text": "Творяй Ангелы Своя духи / и слуги Своя пламень огненный."},
  {"id": "cu-bla-0237", "section": "service", "who": "choir", "text": "Света сый исполнь присно, / и творя хотение, / и скончавая повеления Вседержителя, / начальниче Ангелов, / Гаврииле всеизрядне, / любовию тя чтущия спасай, / присно прося / даровати душам нашим / мир и велию милость."},
  {"id": "cu-bla-0238", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 6-й. Самогласен:"},
  {"id": "cu-bla-0239", "section": "service", "who": "choir", "text": "Послан бысть с Небесе Гавриил Архангел / благовестити Деве зачатие / и, пришед в Назарет, / помышляше в себе, чудеси удивляяся: / о, како, в Вышних непостижим Сый от Девы раждается! / Имеяй престол Небо и подножие землю / во утробу вмещается Девичу! / На Негоже шестокрилатии и многоочитии зрети не могут, / словом единем от Сея воплотитися благоизволи. / Божие есть слово настоящее. / Что убо стою и не глаголю Деве: / радуйся, Благодатная, Господь с Тобою; / радуйся, Чистая Дево; / радуйся, Невесто Неневестная; / радуйся, Мати Живота, / благословен Плод чрева Твоего!"},
  {"id": "cu-bla-0240", "section": "service", "who": "rubric", "text": "Иерей же творит проскомидию в стихиры. Вход со Евангелием,"},
  {"id": "cu-bla-0241", "section": "service", "who": "choir", "text": "Свете тихий:"},
  {"id": "cu-bla-0242", "section": "service", "who": "rubric", "text": "Прокимен, и чтения дне, и праздника две:"},
  {"id": "cu-bla-0243", "section": "service", "who": "priest", "text": "Исхода чтение (глава 3): Вниде Моисей в гору Божию Хорив, явися же ему Ангел Господень в пламени огненне из купины, и виде, яко купина горяше огнем и купина не сгараше. Рече же Моисей: прешед, узрю видение великое сие, что яко не сгарает купина? Якоже виде Господь, яко приступает видети, призва его Господь, из купины глаголя: Моисее, Моисее. Он же рече: что есть? И рече: не приближися семо. Иззуй сапог от ногу твоею: место бо, на немже ты стоиши, земля свята есть. И рече ему: Аз есмь Бог отца твоего, Бог Авраамов, и Бог Исааков, и Бог Иаковль. Отврати же Моисей лице свое, стыдяше бо ся зрети пред Богом. Рече же Господь к Моисею: видя, видех озлобление людей Моих, иже во Египте, и вопль их услышах от насильствующих в делех. Вем бо болезнь их, и снидох, еже изъяти их от руки египтян, и извести их от земли оныя, и ввести их в землю благу и многу, в землю, точащу мед и млеко."},
  {"id": "cu-bla-0244", "section": "service", "who": "priest", "text": "Притчей чтение (глава 8): Господь созда мя начало путей Своих в дела Своя. Прежде век основа мя в начале, прежде неже землю сотворити, и прежде неже бездны соделати, прежде неже произыти источником вод, прежде, неже горам водрузитися, прежде же всех холмов раждает мя. Господь сотвори страны, и пустыни, и концы, населены под Небесем. Егда готовяше небо, с Ним бех, и егда отлучаше Себе престол на ветрех, егда крепки творяше вышния облаки и яко тверды полагаше источники поднебесныя. Внегда полагати морю предел его, и воды не мимо идут уст Его, и крепки творяше основания земли, бех при Нем устрояя подобна. Аз бех, о нейже радовашеся: по вся же дни веселяхся пред лицем Его на всяко время."},
  {"id": "cu-bla-0245", "section": "service", "who": "rubric", "text": "Таже ектения малая, и возглас трисвятаго, и трисвятое."},
  {"id": "cu-bla-0246", "section": "service", "who": "rubric", "text": "Аще случится Благовещение в субботу или в неделю, поем Литургию, и Блаженны от канона праздника, песнь 3-я на 4, и 6-я на 4. Аще изволит предстоятель, поем антифоны праздника."},
  {"id": "cu-bla-0247", "section": "service", "who": "priest", "text": "Антифон 1, глас 2. Стих 1:"},
  {"id": "cu-bla-0248", "section": "service", "who": "priest", "text": "Боже, суд Твой Цареви даждь, / и правду Твою Сыну Цареву."},
  {"id": "cu-bla-0249", "section": "service", "who": "priest", "text": "Молитвами Богородицы, Спасе, / спаси нас. Стих 2:"},
  {"id": "cu-bla-0250", "section": "service", "who": "priest", "text": "Да восприимут горы мир людем / и холми правду."},
  {"id": "cu-bla-0251", "section": "service", "who": "priest", "text": "Молитвами Богородицы, Спасе, / спаси нас. Стих 3:"},
  {"id": "cu-bla-0252", "section": "service", "who": "priest", "text": "Благовестите день от дне / спасение Бога нашего."},
  {"id": "cu-bla-0253", "section": "service", "who": "priest", "text": "Молитвами Богородицы, Спасе, / спаси нас. Стих 4:"},
  {"id": "cu-bla-0254", "section": "service", "who": "priest", "text": "Клятся Господь Давиду истиною / и не отвержется ея."},
  {"id": "cu-bla-0255", "section": "service", "who": "priest", "text": "Молитвами Богородицы, Спасе, / спаси нас. Слава, и ныне: Молитвами Богородицы, Спасе, / спаси нас."},
  {"id": "cu-bla-0256", "section": "service", "who": "priest", "text": "Антифон 2, глас 2. Стих 1:"},
  {"id": "cu-bla-0257", "section": "service", "who": "priest", "text": "Снидет, яко дождь на руно, / и яко капля, каплющая на землю."},
  {"id": "cu-bla-0258", "section": "service", "who": "priest", "text": "Спаси ны, Сыне Божий, / нас ради воплотивыйся, поющия Ти: аллилуиа. Стих 2:"},
  {"id": "cu-bla-0259", "section": "service", "who": "priest", "text": "Освятил есть / селение Свое Вышний."},
  {"id": "cu-bla-0260", "section": "service", "who": "priest", "text": "Спаси ны, Сыне Божий, / нас ради воплотивыйся, поющия Ти: аллилуиа. Стих 3:"},
  {"id": "cu-bla-0261", "section": "service", "who": "priest", "text": "Бог яве приидет, / Бог наш, и не премолчит."},
  {"id": "cu-bla-0262", "section": "service", "who": "priest", "text": "Спаси ны, Сыне Божий, / нас ради воплотивыйся, поющия Ти: аллилуиа. Стих 4:"},
  {"id": "cu-bla-0263", "section": "service", "who": "priest", "text": "Возсияет во днех Его правда / и множество мира."},
  {"id": "cu-bla-0264", "section": "service", "who": "priest", "text": "Спаси ны, Сыне Божий, / нас ради воплотивыйся, поющия Ти: аллилуиа."},
  {"id": "cu-bla-0265", "section": "service", "who": "priest", "text": "Слава, и ныне: Единородный Сыне:"},
  {"id": "cu-bla-0266", "section": "service", "who": "priest", "text": "Антифон 3, глас 4. Стих 1:"},
  {"id": "cu-bla-0267", "section": "service", "who": "priest", "text": "Будет имя Его / благословено во веки."},
  {"id": "cu-bla-0268", "section": "service", "who": "priest", "text": "Тропарь, глас 4: Днесь спасения нашего главизна / и еже от века таинства явление: / Сын Божий Сын Девы бывает, / и Гавриил благодать благовествует. / Темже и мы с ним Богородице возопиим: / радуйся, Благодатная, / Господь с Тобою. Стих 2:"},
  {"id": "cu-bla-0269", "section": "service", "who": "priest", "text": "Благословен Господь Бог Израилев, / творяй чудеса Един. Тропарь:"},
  {"id": "cu-bla-0270", "section": "service", "who": "priest", "text": "Днесь спасения нашего главизна: Стих 3:"},
  {"id": "cu-bla-0271", "section": "service", "who": "priest", "text": "Благословено имя славы Его / во век и в век века. Тропарь:"},
  {"id": "cu-bla-0272", "section": "service", "who": "priest", "text": "Днесь спасения нашего главизна:"},
  {"id": "cu-bla-0273", "section": "service", "who": "priest", "text": "Вход. Стих:"},
  {"id": "cu-bla-0274", "section": "service", "who": "priest", "text": "Благовестите день от дне / спасение Бога нашего. Мы же:"},
  {"id": "cu-bla-0275", "section": "service", "who": "priest", "text": "Приидите, поклонимся и припадем ко Христу, / спаси ны, Сыне Божий, / нас ради воплотивыйся, поющия Ти: / аллилуиа."},
  {"id": "cu-bla-0276", "section": "service", "who": "priest", "text": "Тропарь, глас 4: Днесь спасения нашего главизна / и еже от века таинства явление: / Сын Божий Сын Девы бывает, / и Гавриил благодать благовествует. / Темже и мы с ним Богородице возопиим: / радуйся, Благодатная, / Господь с Тобою."},
  {"id": "cu-bla-0277", "section": "service", "who": "priest", "text": "Слава, и ныне:"},
  {"id": "cu-bla-0278", "section": "service", "who": "priest", "text": "Кондак, глас 8: Взбранной Воеводе победительная, / яко избавльшеся от злых, / благодарственная восписуем Ти, раби Твои, Богородице, / но, яко имущая державу непобедимую, / от всяких нас бед свободи, да зовем Ти: / радуйся, Невесто Неневестная."},
  {"id": "cu-bla-0279", "section": "service", "who": "priest", "text": "Прокимен, глас 4: Благовестите день от дне / спасение Бога нашего. Стих:"},
  {"id": "cu-bla-0280", "section": "service", "who": "priest", "text": "Воспойте Господеви песнь нову, воспойте Господеви вся земля."},
  {"id": "cu-bla-0281", "section": "service", "who": "priest", "text": "Апостол ко Евреем, зачало 306:"},
  {"id": "cu-bla-0282", "section": "service", "who": "priest", "text": "Братие, святяй и освящаемии, от Eдинаго вси: eяже ради вины не стыдится братию нарицати их, глаголя: Возвещу имя Твое братии Моей, посреде церкве воспою Тя. И паки: Аз буду надеяся Нань. И паки: се Аз и дети, яже Ми дал eсть Бог. Понеже убо дети приобщишася плоти и крови, и Той приискренне приобщися техже, да смертию упразднит имущаго державу смерти, сиречь, диавола: и избавит сих, eлицы страхом смерти чрез все житие повинни беша работе. Не от ангел убо когда {воистинну} приемлет, но от семене Авраамова приемлет: отнюдуже должен бе по всему подобитися братии, да милостив будет и верен первосвященник в тех, яже к Богу, во eже очистити грехи людския. В немже бо пострада Сам искушен быв, может и искушаeмым помощи."},
  {"id": "cu-bla-0283", "section": "service", "who": "priest", "text": "Аллилуия, глас 1: Снидет, яко дождь на руно, / и, яко капля, каплющая на землю. Стих:"},
  {"id": "cu-bla-0284", "section": "service", "who": "priest", "text": "Будет имя Его благословенно во веки, прежде солнца пребывает имя Его."},
  {"id": "cu-bla-0285", "section": "service", "who": "priest", "text": "Евангелие от Луки, зачало 3: Во днех онех, зачат Eлисавет жена Захариина, и таяшеся месяц пять, глаголющи: яко тако мне сотвори Господь во дни, в няже призре отъяти поношение мое в человецех. В месяц же шестый послан бысть ангел Гавриил от Бога во град Галилейский, eмуже имя Назарет, к Деве обрученней мужеви, eмуже имя Иосиф, от дому Давидова: и имя Деве, Мариам. И вшед к Ней ангел, рече: радуйся Благодатная, Господь с Тобою: благословена Ты в женах. Oна же видевши смутися о словеси eго, и помышляше, каково будет целование сие. И рече ангел Eй: не бойся Мариам, обрете бо благодать от Бога. И се зачнеши во чреве, и родиши Сына, и наречеши имя Eму Иисус. Сей будет велий, и Сын Вышняго наречется: и даст Eму Господь Бог престол Давида oтца Eго: и воцарится в дому Иаковли во веки, и Царствию Eго не будет конца. Рече же Мариам ко ангелу: како будет сие, идеже мужа не знаю? И отвещав ангел, рече Eй: Дух Святый найдет на Тя, и сила Вышняго осенит Тя: темже и раждаемое Свято, наречется Сын Божий. И се Eлисавет, южика Твоя, и та зачат сына в старости своей: и сей месяц шестый eсть eй, нарицаемей неплоды. Яко не изнеможет от Бога всяк глагол. Рече же Мариам: се Раба Господня, буди Мне по глаголу твоему. И отыде от Нея ангел."},
  {"id": "cu-bla-0286", "section": "service", "who": "rubric", "text": "И прочая Божественныя Литургии Златоустаго."},
  {"id": "cu-bla-0287", "section": "service", "who": "priest", "text": "Вместо Достойно: Благовествуй, земле, радость велию, / хвалите, небеса, Божию славу."},
  {"id": "cu-bla-0288", "section": "service", "who": "rubric", "text": "Ирмос, глас 4:"},
  {"id": "cu-bla-0289", "section": "service", "who": "priest", "text": "Яко одушевленному Божию кивоту, / да никакоже коснется рука скверных, / устне же верных, Богородице, немолчно, / глас Ангела воспевающе, / с радостию да вопиют: / радуйся, Благодатная, / Господь с Тобою."},
  {"id": "cu-bla-0290", "section": "service", "who": "priest", "text": "Причастен: Избра Господь Сиона / и изволи его в жилище Себе. / Аллилуиа, трижды."},
];

